def max_removals(s):
    n = len(s)
    if n == 1:
        return 0

    # Create a list to store the number of removals for each character
    removals = [0] * n

    # Calculate the number of removals for each character
    for i in range(n):
        if i == 0:
            if ord(s[i]) + 1 == ord(s[i + 1]):
                removals[i] = 1
        elif i == n - 1:
            if ord(s[i]) + 1 == ord(s[i - 1]):
                removals[i] = 1
        else:
            if ord(s[i]) + 1 == ord(s[i - 1]) or ord(s[i]) + 1 == ord(s[i + 1]):
                removals[i] = 1

    # Use dynamic programming to find the maximum number of removals
    dp = [0] * n
    for i in range(n):
        dp[i] = max(dp[i - 1], removals[i] + (dp[i - 2] if i >= 2 else 0))

    return dp[-1]

